extension Engine where Policy == StaticRecordStringPolicy {
    /// Raises `labelled.taken` with its payload, binding the event and the payload's
    /// values in one call so the pairing of a name and a type cannot be
    /// constructed inconsistently (NL-to-IR Item C1 Path A). Both carriers are
    /// filled: the typed one a native expression reads, and `data`, which is what
    /// every other reader of `_event.data` binds it from.
    public func raiseLabelledTaken(sensor: UInt8, label: String) {
        raiseExternalWithMeta(
            EventWithMetadata(
                StaticRecordStringEvent.labelledTaken,
                metadata: EventMetadata(
                    data: payloadJSON(.integer("sensor", sensor), .text("label", label)),
                    eventType: .externalEvent,
                    typedPayload: StaticRecordStringLabelledTakenPayload(sensor: sensor, label: label)
                )
            )
        )
    }
